-- Entity: product (table insurance_products)

DROP VIEW IF EXISTS learninsurancedb.vw_insurance_products CASCADE;
CREATE VIEW learninsurancedb.vw_insurance_products AS
SELECT t.*,
       pt.name AS product_type_name, pt.code AS product_type_code, pt.icon AS product_type_icon,
       CASE WHEN t.effective_from > CURRENT_DATE THEN 'Upcoming'
            WHEN t.effective_to IS NOT NULL AND t.effective_to < CURRENT_DATE THEN 'Expired'
            ELSE 'Live' END AS lifecycle
FROM learninsurancedb.insurance_products t
JOIN learninsurancedb.insurance_product_types pt ON pt.id = t.product_type_id;

-- LIST: search + filters + sort + paging. Returns { items, totalCount, page, pageSize }
DROP FUNCTION IF EXISTS learninsurancedb.fn_product_get_all(text, int, int, text, text, jsonb);
CREATE FUNCTION learninsurancedb.fn_product_get_all(
    p_search    text  DEFAULT NULL,
