    p_page_size int   DEFAULT 10,
    p_sort_by   text  DEFAULT NULL,
    p_sort_dir  text  DEFAULT NULL,
    p_filters   jsonb DEFAULT '{}'::jsonb
) RETURNS jsonb
LANGUAGE plpgsql STABLE AS $fn$
DECLARE
    v_page   int := GREATEST(COALESCE(p_page, 1), 1);
    v_size   int := LEAST(GREATEST(COALESCE(p_page_size, 10), 1), 500);
    v_sort   text := learninsurancedb.fn_to_snake(p_sort_by);
    v_dir    text := CASE WHEN lower(COALESCE(p_sort_dir, 'ASC')) = 'asc' THEN 'ASC' ELSE 'DESC' END;
    v_where  text := 'WHERE TRUE';
    v_like   text;
    v_key    text;
    v_val    text;
    v_col    text;
    v_total  bigint;
    v_items  jsonb;
BEGIN
    IF v_sort IS NULL OR NOT (v_sort = ANY (ARRAY['name', 'product_type_id', 'description', 'base_rate', 'min_sum_insured', 'max_sum_insured', 'effective_from', 'effective_to', 'id', 'created_date', 'modified_date', 'is_active', 'product_code', 'product_type_name', 'lifecycle'])) THEN
        v_sort := 'product_code';
        IF p_sort_by IS NULL THEN v_dir := 'ASC'; END IF;
    END IF;

    IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
        v_like := '%' || btrim(p_search) || '%';
        v_where := v_where || format(' AND (product_code::text ILIKE %1$L OR name::text ILIKE %1$L OR description::text ILIKE %1$L OR product_type_name::text ILIKE %1$L)', v_like);
    END IF;

    FOR v_key, v_val IN SELECT key, value FROM jsonb_each_text(COALESCE(p_filters, '{}'::jsonb)) LOOP
        v_col := learninsurancedb.fn_to_snake(v_key);
        IF v_col = ANY (ARRAY['is_active', 'product_type_id', 'product_type_code', 'lifecycle']) AND COALESCE(v_val, '') <> '' THEN
            v_where := v_where || format(' AND %I::text = %L', v_col, v_val);
        END IF;
    END LOOP;

    EXECUTE format('SELECT count(*) FROM learninsurancedb.vw_insurance_products %s', v_where) INTO v_total;
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(learninsurancedb.fn_to_camel(to_jsonb(q))), ''[]''::jsonb)
         FROM (SELECT * FROM learninsurancedb.vw_insurance_products %s ORDER BY %I %s, id DESC LIMIT %s OFFSET %s) q',
        v_where, v_sort, v_dir, v_size, (v_page - 1) * v_size) INTO v_items;

    RETURN jsonb_build_object('items', v_items, 'totalCount', v_total, 'page', v_page, 'pageSize', v_size);
