-- GET BY ID: returns the row as JSON, or NULL when not found
CREATE OR REPLACE FUNCTION learninsurancedb.fn_product_get_by_id(p_id bigint) RETURNS jsonb
LANGUAGE sql STABLE AS $fn$
    SELECT learninsurancedb.fn_to_camel(to_jsonb(v)) FROM learninsurancedb.vw_insurance_products v WHERE v.id = p_id;
