-- CREATE: p_data uses camelCase keys
CREATE OR REPLACE FUNCTION learninsurancedb.fn_product_create(p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE v_id bigint;
BEGIN
    INSERT INTO learninsurancedb.insurance_products (name, product_type_id, description, base_rate, min_sum_insured, max_sum_insured, effective_from, effective_to, created_by)
    VALUES (NULLIF(p_data->>'name', ''),
            NULLIF(p_data->>'productTypeId', '')::bigint,
            NULLIF(p_data->>'description', ''),
            NULLIF(p_data->>'baseRate', '')::numeric,
            COALESCE(NULLIF(p_data->>'minSumInsured', '')::numeric, 0),
            NULLIF(p_data->>'maxSumInsured', '')::numeric,
            COALESCE(NULLIF(p_data->>'effectiveFrom', '')::date, CURRENT_DATE),
            NULLIF(p_data->>'effectiveTo', '')::date,
            COALESCE(p_user, 'system'))
    RETURNING id INTO v_id;
    RETURN learninsurancedb.fn_product_get_by_id(v_id);
END
$fn$;


-- UPDATE: only keys present in p_data are changed (so partial and full updates both work)
CREATE OR REPLACE FUNCTION learninsurancedb.fn_product_update(p_id bigint, p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.insurance_products SET
        name = CASE WHEN p_data ? 'name' THEN NULLIF(p_data->>'name', '') ELSE name END,
        product_type_id = CASE WHEN p_data ? 'productTypeId' THEN NULLIF(p_data->>'productTypeId', '')::bigint ELSE product_type_id END,
        description = CASE WHEN p_data ? 'description' THEN NULLIF(p_data->>'description', '') ELSE description END,
        base_rate = CASE WHEN p_data ? 'baseRate' THEN NULLIF(p_data->>'baseRate', '')::numeric ELSE base_rate END,
        min_sum_insured = CASE WHEN p_data ? 'minSumInsured' THEN COALESCE(NULLIF(p_data->>'minSumInsured', '')::numeric, 0) ELSE min_sum_insured END,
        max_sum_insured = CASE WHEN p_data ? 'maxSumInsured' THEN NULLIF(p_data->>'maxSumInsured', '')::numeric ELSE max_sum_insured END,
        effective_from = CASE WHEN p_data ? 'effectiveFrom' THEN COALESCE(NULLIF(p_data->>'effectiveFrom', '')::date, CURRENT_DATE) ELSE effective_from END,
        effective_to = CASE WHEN p_data ? 'effectiveTo' THEN NULLIF(p_data->>'effectiveTo', '')::date ELSE effective_to END,
        modified_date = now(),
        modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_product_get_by_id(p_id);
END
$fn$;


-- SET ACTIVE: soft delete / restore
CREATE OR REPLACE FUNCTION learninsurancedb.fn_product_set_active(p_id bigint, p_active boolean, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.insurance_products SET is_active = p_active, modified_date = now(), modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_product_get_by_id(p_id);
END
$fn$;

-- DELETE (soft): sets is_active = false
CREATE OR REPLACE FUNCTION learninsurancedb.fn_product_delete(p_id bigint, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM learninsurancedb.fn_product_set_active(p_id, FALSE, p_user);
    RETURN jsonb_build_object('id', p_id, 'deleted', TRUE);
END
$fn$;
